     * Create a CommandLine instance via the private constructor
     * CommandLine(List<String>, List<Option>, Consumer<Option>)
     */
    private CommandLine newCommandLine() throws Exception {
        Constructor<CommandLine> ctor =
                CommandLine.class.getDeclaredConstructor(java.util.List.class, java.util.List.class, Consumer.class);
        ctor.setAccessible(true);
        // supply empty lists and null deprecatedHandler
        return ctor.newInstance(new LinkedList<String>(), new ArrayList<Option>(), null);
    }

    @Test
    public void returnsDefaultWhenOptionIsNull() throws Exception {
        CommandLine cmd = newCommandLine();
        String result = cmd.getOptionValue(null, "defaultValue");
        assertEquals("defaultValue", result);
    }

    @Test
    public void returnsNullWhenDefaultIsNullAndOptionIsNull() throws Exception {
        CommandLine cmd = newCommandLine();
        String result = cmd.getOptionValue(null, null);
        assertNull(result);
    }

    @Test
    public void privateSupplierOverloadInvokesSupplierWhenOptionIsNull() throws Exception {
        CommandLine cmd = newCommandLine();

        // Access the supplier-based overload reflectively:
        Method supplierMethod = CommandLine.class.getDeclaredMethod("getOptionValue", Option.class, Supplier.class);
        supplierMethod.setAccessible(true);

        AtomicInteger invoked = new AtomicInteger(0);
        Supplier<String> supplier = () -> {
