            return "suppliedValue";
        };

        Object returned = supplierMethod.invoke(cmd, new Object[]{null, supplier});
        assertEquals("suppliedValue", returned);
        assertEquals(1, invoked.get(), "Supplier should have been invoked exactly once");
    }
